import type { Cell, Hex, OpenResult, Script, Transaction } from '../src/types.js';
/** Shape of fixtures generated by the pinned Rust SDK. Unknown protocol payloads stay opaque. */
export interface ChannelFixture {
  tenantId: string;
  publicKey: string;
  nodePublicKey: string;
  root: string;
  snapshot: string;
  session: string;
  reserve: Hex;
  script: Script;
  commitmentLock: Script;
  inputCell: Cell;
  fundingCell: Cell;
  proposal: OpenResult;
  request: Record<string, unknown>;
  statuses: (Record<string, unknown> & {
    settlement: { local_amount: Hex; [key: string]: unknown };
  })[];
  closeStatus: Record<string, unknown>;
  closeTransaction: Transaction;
  invoice: string;
  invoiceObject: unknown;
}
export type RpcParams = Record<string, unknown>;
export interface RpcRequest {
  id: number;
  method: string;
  params: RpcParams[];
}
export interface RpcRequestOptions extends RequestInit {
  body: string;
  headers: Record<string, string>;
}
export type RpcHandler = (
  method: string,
  params: RpcParams,
  options: RpcRequestOptions,
  body: RpcRequest,
) => unknown | Promise<unknown>;
